import{_ as s,c as e,o as i,ag as t}from"./chunks/framework.B-aGGnuW.js";const k=JSON.parse('{"title":"Drivers and useful packages","description":"","frontmatter":{},"headers":[],"relativePath":"installation/useful-packages.md","filePath":"installation/useful-packages.md","lastUpdated":1792149212000}'),n={name:"installation/useful-packages.md"};function l(r,a,h,p,o,d){return i(),e("div",null,[...a[0]||(a[0]=[t(`<h1 id="drivers-and-useful-packages" tabindex="-1">Drivers and useful packages <a class="header-anchor" href="#drivers-and-useful-packages" aria-label="Permalink to &quot;Drivers and useful packages&quot;">​</a></h1><p>Install the graphics and audio packages needed by your desktop before continuing to the bootloader page. The remaining sections are optional. Commands run as root inside the chroot.</p><h2 id="graphics-drivers" tabindex="-1">Graphics drivers <a class="header-anchor" href="#graphics-drivers" aria-label="Permalink to &quot;Graphics drivers&quot;">​</a></h2><p>Identify your hardware:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">lspci</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -k</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -E</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;(VGA|3D|Display)&#39;</span></span></code></pre></div><p>Install drivers for each GPU you use, including both GPUs on a hybrid laptop. The commands below target current hardware; consult the linked wiki pages for older generations.</p><h3 id="amd" tabindex="-1">AMD <a class="header-anchor" href="#amd" aria-label="Permalink to &quot;AMD&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mesa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vulkan-radeon</span></span></code></pre></div><p>For Steam and other 32-bit graphics applications, enable multilib and add:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lib32-mesa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lib32-vulkan-radeon</span></span></code></pre></div><p>VA-API support is included in Mesa. See <a href="https://wiki.archlinux.org/title/AMDGPU" target="_blank" rel="noreferrer">AMDGPU</a> for older GPUs and hardware video acceleration.</p><h3 id="intel" tabindex="-1">Intel <a class="header-anchor" href="#intel" aria-label="Permalink to &quot;Intel&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mesa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> vulkan-intel</span></span></code></pre></div><p>For 32-bit graphics applications:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lib32-mesa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> lib32-vulkan-intel</span></span></code></pre></div><p>Video acceleration packages depend on the GPU generation; see <a href="https://wiki.archlinux.org/title/Intel_graphics" target="_blank" rel="noreferrer">Intel graphics</a>. The legacy <code>xf86-video-intel</code> Xorg driver is not a default requirement.</p><h3 id="nvidia" tabindex="-1">NVIDIA <a class="header-anchor" href="#nvidia" aria-label="Permalink to &quot;NVIDIA&quot;">​</a></h3><p>Select the driver by GPU generation. The current open kernel modules support <strong>Turing and newer</strong>, not every NVIDIA card. For the <code>linux</code> kernel installed by this guide:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia-open</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nvidia-utils</span></span></code></pre></div><p>For Steam, add <code>lib32-nvidia-utils</code> after enabling multilib. Use <code>nvidia-open-lts</code> with <code>linux-lts</code>, or <code>nvidia-open-dkms</code> plus matching kernel headers for other kernels.</p><p>Maxwell, Pascal and Volta need the legacy <code>nvidia-580xx-dkms</code> AUR branch and matching <code>nvidia-580xx-utils</code> (plus <code>lib32-nvidia-580xx-utils</code> for 32-bit applications). These require <a href="/post-installation/#aur-packages">AUR setup</a> as a regular user and headers for each installed kernel. For a fresh install on this hardware, complete the base system and boot into a console first; postpone enabling a graphical login until the driver is installed. If you already enabled a display manager, disable that service before rebooting. Older cards need other legacy branches or Nouveau. Do not mix legacy and current NVIDIA userspace libraries.</p><p>Read <a href="https://wiki.archlinux.org/title/NVIDIA" target="_blank" rel="noreferrer">NVIDIA</a> for the hardware support table, hybrid graphics and power-management caveats. Arch&#39;s <a href="https://archlinux.org/news/nvidia-590-driver-drops-pascal-support-main-packages-switch-to-open-kernel-modules/" target="_blank" rel="noreferrer">driver transition notice</a> explains the package change.</p><h3 id="initramfs-and-virtual-machines" tabindex="-1">Initramfs and virtual machines <a class="header-anchor" href="#initramfs-and-virtual-machines" aria-label="Permalink to &quot;Initramfs and virtual machines&quot;">​</a></h3><p>Keep the default <code>kms</code> hook for in-tree drivers. Only add explicit modules when your hardware requires them, preserving any existing <code>MODULES</code> entries; see <a href="https://wiki.archlinux.org/title/Kernel_mode_setting#Early_KMS_start" target="_blank" rel="noreferrer">early KMS</a>. The next page regenerates the initramfs after configuration.</p><p>For a VM, install guest integration appropriate to its hypervisor and virtual GPU: <a href="https://wiki.archlinux.org/title/VirtualBox/Install_Arch_Linux_as_a_guest" target="_blank" rel="noreferrer">VirtualBox</a>, <a href="https://wiki.archlinux.org/title/VMware/Install_Arch_Linux_as_a_guest" target="_blank" rel="noreferrer">VMware</a>, or <a href="https://wiki.archlinux.org/title/QEMU" target="_blank" rel="noreferrer">QEMU</a>. The VMware Xorg driver is not a universal VM driver.</p><h2 id="audio" tabindex="-1">Audio <a class="header-anchor" href="#audio" aria-label="Permalink to &quot;Audio&quot;">​</a></h2><p>Use PipeWire with WirePlumber:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipewire</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipewire-alsa</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pipewire-pulse</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> wireplumber</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> alsa-utils</span></span></code></pre></div><p>The user services start with the desktop session; do not enable them as system services. Install <code>pipewire-jack</code> only if you need JACK compatibility. Plasma includes volume controls; <code>pavucontrol</code> or <code>pavucontrol-qt</code> are optional alternatives. See <a href="https://wiki.archlinux.org/title/PipeWire" target="_blank" rel="noreferrer">PipeWire</a>.</p><h2 id="bluetooth" tabindex="-1">Bluetooth <a class="header-anchor" href="#bluetooth" aria-label="Permalink to &quot;Bluetooth&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bluez</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bluez-utils</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bluetooth.service</span></span></code></pre></div><p>Plasma includes Bluedevil; other desktops can use their own Bluetooth settings or <code>blueman</code>. PipeWire does not need <code>pulseaudio-bluetooth</code>.</p><h2 id="printing-and-scanning" tabindex="-1">Printing and scanning <a class="header-anchor" href="#printing-and-scanning" aria-label="Permalink to &quot;Printing and scanning&quot;">​</a></h2><p>Start with driverless printing for supported IPP printers:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cups</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> cups.service</span></span></code></pre></div><p>For network printer discovery, install <code>avahi</code> and enable <code>avahi-daemon.service</code>. Use Plasma&#39;s <code>print-manager</code> or <code>system-config-printer</code> to add printers. Install <code>gutenprint</code>, <code>hplip</code> or other device-specific drivers only if your model needs them. See <a href="https://wiki.archlinux.org/title/CUPS" target="_blank" rel="noreferrer">CUPS</a>.</p><p>For supported network scanners, install <code>sane-airscan</code> with <code>skanlite</code> (Qt) or <code>simple-scan</code> (GTK). Supported USB IPP devices may need <code>ipp-usb</code>. Local scanning does not require enabling <code>saned.socket</code>; see <a href="https://wiki.archlinux.org/title/SANE" target="_blank" rel="noreferrer">SANE</a>.</p><h2 id="ssd-maintenance" tabindex="-1">SSD maintenance <a class="header-anchor" href="#ssd-maintenance" aria-label="Permalink to &quot;SSD maintenance&quot;">​</a></h2><p>For supported SSDs:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">systemctl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> enable</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fstrim.timer</span></span></code></pre></div><p>Encrypted systems also need a deliberate <a href="/encryption/#header-backup-and-ssd-discard">discard configuration</a>. The timer alone cannot trim through a LUKS mapping that blocks discard.</p><h2 id="file-tools-and-network-shares" tabindex="-1">File tools and network shares <a class="header-anchor" href="#file-tools-and-network-shares" aria-label="Permalink to &quot;File tools and network shares&quot;">​</a></h2><p>Install what you use, for example:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 7zip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unzip</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> unrar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> rsync</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> xdg-user-dirs</span></span></code></pre></div><p>Use <code>exfatprogs</code> for native exFAT filesystem tools. Linux includes the <code>ntfs3</code> driver; <code>ntfs-3g</code> remains an alternative. Network shares may need <code>nfs-utils</code> or <code>cifs-utils</code>, and GTK file managers commonly use <code>gvfs</code> integrations.</p><p>NetworkManager is already installed and enabled. Add VPN plugins only for the VPN you use; do not enable another network manager for the same interface.</p><h2 id="android-tools" tabindex="-1">Android tools <a class="header-anchor" href="#android-tools" aria-label="Permalink to &quot;Android tools&quot;">​</a></h2><p>For ADB access as your regular user:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android-tools</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> android-udev</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">usermod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -aG</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> adbusers</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yourusername</span></span></code></pre></div><h2 id="alternative-shells" tabindex="-1">Alternative shells <a class="header-anchor" href="#alternative-shells" aria-label="Permalink to &quot;Alternative shells&quot;">​</a></h2><p>For Zsh:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> zsh-completions</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/zsh</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yourusername</span></span></code></pre></div><p>Or for Fish:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pacman</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fish</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">chsh</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /usr/bin/fish</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yourusername</span></span></code></pre></div>`,54)])])}const g=s(n,[["render",l]]);export{k as __pageData,g as default};
